def check_graph():
    edges = [
        (0, 7), (0, 8), (0, 10),
        (1, 8), (1, 9), (1, 11),
        (2, 9), (2, 10), (2, 12),
        (3, 10), (3, 11), (3, 13),
        (4, 7), (4, 11), (4, 12),
        (5, 8), (5, 12), (5, 13),
        (6, 7), (6, 9), (6, 13)
    ]

    # Build adjacency list
    adj = {i: [] for i in range(14)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check degrees
    for i in range(14):
        if len(adj[i]) != 3:
            print(f"Vertex {i} has degree {len(adj[i])}")
            return False

    # Check girth using BFS
    min_cycle = float('inf')
    for start in range(14):
        # BFS to find shortest cycle through start
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (node, parent, distance)
        while queue:
            node, parent, dist = queue.pop(0)
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    cycle_len = dist + visited[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)
                else:
                    visited[neighbor] = dist + 1
                    queue.append((neighbor, node, dist + 1))

    print(f"Minimum degree: {min(len(adj[i]) for i in range(14))}")
    print(f"Maximum degree: {max(len(adj[i]) for i in range(14))}")
    print(f"Girth: {min_cycle}")
    print(f"Number of edges: {len(edges)}")

    return min_cycle >= 5

print("Graph valid:", check_graph())
